//! A lemon-compatible LALR(1) parser generator and its push-parser driver.
//!
//! RediSearch parses queries with parsers generated by SQLite's lemon (public domain), so ours
//! must accept the same language, reduce in the same order and detect a syntax error at the same
//! token. That is only true if we build lemon's automaton, not just "an" LALR(1) automaton:
//! lemon's default reductions fire before an error is noticed, fallback tokens are only tried
//! when a token has no explicit action, and its state numbering is part of the tables we compare
//! against. Everything below follows `lemon.c` step by step:
//!
//! - [`Grammar::build`] runs `FindRulePrecedences`, `FindFirstSets`, `FindStates` (depth-first,
//!   so states are created in lemon's order), `FindLinks`, `FindFollowSets`, `FindActions` with
//!   `resolve_conflict`, then `CompressTables` (the most frequent reduce of a state becomes its
//!   default, shifts into states that can only reduce become SHIFTREDUCE, unit rules without code
//!   are bypassed) and `ResortStates` (the final numbering, with the tail of auto-reduce states
//!   dropped). Rules are numbered as lemon numbers them: rules with an action first, in file
//!   order, then the rules without one.
//! - [`Parser`] is `lempar.c`'s `Parse()`: one token per call, the pending reduce a SHIFTREDUCE
//!   leaves on the stack, the fixed-depth stack and its overflow handling, and lemon's error
//!   handling for grammars without an `error` symbol (`yyerrcnt`, the discarded token,
//!   `%parse_failure` at end of input), with or without `YYNOERRORRECOVERY`.
//!
//! Lemon's optimisations are reproduced because they are observable:
//!
//! - A state's most frequent reduce becomes its default for every terminal without an explicit
//!   action, error lookaheads included, so reductions run before an error is detected (in a
//!   later state). A `%fallback` token is only retried when its own action is not explicit, so
//!   a token whose action was folded into the default now falls back first.
//! - A SHIFTREDUCE pushes the token with the reduce pending; the reduce runs when the next token
//!   is fed, before that token is looked up, as the target state's default would. It differs
//!   from plain LALR only where the target state also had `%nonassoc` error actions: lemon
//!   ignores them (see the `nonassoc` test).
//! - A SHIFTREDUCE on a nonterminal by a unit rule without code takes the action of the rule's
//!   left side, so that rule is never reduced (the reduce callback never sees it).
//!
//! Not supported, as neither RediSearch grammar uses them: the `error` symbol and its recovery,
//! `%wildcard` and `%token_class` (multi-terminals).

use std::collections::HashMap;
use std::fmt;

/// A terminal or nonterminal. `0` is `$`, the end of input; terminals come first, as in lemon.
pub type Symbol = u16;
/// A rule, numbered as lemon numbers it (its `iRule`).
pub type RuleId = u16;
/// A state of the final (resorted) automaton.
pub type StateId = u16;

/// The end-of-input token, lemon's `$`.
pub const EOF: Symbol = 0;

/// `%left`, `%right` and `%nonassoc`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Assoc {
    Left,
    Right,
    Nonassoc,
}

#[derive(Clone, Debug)]
struct SymbolDef {
    name: String,
    terminal: bool,
    /// Precedence level (1 for the first declaration line) and associativity.
    prec: Option<(i32, Assoc)>,
    fallback: Option<Symbol>,
}

#[derive(Clone, Debug)]
struct RuleDef {
    lhs: Symbol,
    rhs: Vec<Symbol>,
    /// The explicit `[SYMBOL]` precedence mark.
    prec: Option<Symbol>,
    /// Whether the rule has C code in the grammar file; lemon numbers such rules first and only
    /// bypasses unit rules that have none.
    has_action: bool,
}

/// A grammar as lemon reads it from a `.y` file: declare the terminals (in lemon's numbering
/// order, `$` is implicit), the precedence lines, the nonterminals, then the rules in file order.
#[derive(Clone, Debug)]
pub struct Grammar {
    symbols: Vec<SymbolDef>,
    n_terminals: usize,
    rules: Vec<RuleDef>,
    start: Option<Symbol>,
    stack_size: usize,
    prec_level: i32,
}

/// A grammar lemon would refuse to generate a parser for.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GrammarError(pub String);

impl fmt::Display for GrammarError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for GrammarError {}

impl Default for Grammar {
    fn default() -> Self {
        Self::new()
    }
}

impl Grammar {
    /// An empty grammar with lemon's `$` (symbol 0) and its default stack depth of 100.
    pub fn new() -> Self {
        Grammar {
            symbols: vec![SymbolDef { name: "$".into(), terminal: true, prec: None, fallback: None }],
            n_terminals: 1,
            rules: Vec::new(),
            start: None,
            stack_size: 100,
            prec_level: 0,
        }
    }

    /// Declares the next terminal. All terminals must be declared before any nonterminal.
    pub fn terminal(&mut self, name: &str) -> Symbol {
        assert_eq!(self.n_terminals, self.symbols.len(), "terminal {name} declared after a nonterminal");
        self.n_terminals += 1;
        self.push_symbol(name, true)
    }

    /// Declares the next nonterminal.
    pub fn nonterminal(&mut self, name: &str) -> Symbol {
        self.push_symbol(name, false)
    }

    fn push_symbol(&mut self, name: &str, terminal: bool) -> Symbol {
        assert!(self.symbols.iter().all(|s| s.name != name), "symbol {name} declared twice");
        self.symbols.push(SymbolDef { name: name.into(), terminal, prec: None, fallback: None });
        Symbol::try_from(self.symbols.len() - 1).expect("too many symbols")
    }

    /// One `%left` / `%right` / `%nonassoc` line: each line binds tighter than the previous ones.
    pub fn precedence(&mut self, assoc: Assoc, symbols: &[Symbol]) {
        self.prec_level += 1;
        for &s in symbols {
            let def = &mut self.symbols[s as usize];
            assert!(def.prec.is_none(), "symbol {} has already been given a precedence", def.name);
            def.prec = Some((self.prec_level, assoc));
        }
    }

    /// `%left`.
    pub fn left(&mut self, symbols: &[Symbol]) {
        self.precedence(Assoc::Left, symbols);
    }

    /// `%right`.
    pub fn right(&mut self, symbols: &[Symbol]) {
        self.precedence(Assoc::Right, symbols);
    }

    /// `%nonassoc`.
    pub fn nonassoc(&mut self, symbols: &[Symbol]) {
        self.precedence(Assoc::Nonassoc, symbols);
    }

    /// `%fallback TO FROM...`: a token with no action in the current state is retried as `to`.
    pub fn fallback(&mut self, to: Symbol, from: &[Symbol]) {
        assert!(self.symbols[to as usize].terminal, "%fallback argument should be a token");
        for &s in from {
            let def = &mut self.symbols[s as usize];
            assert!(def.terminal, "%fallback argument {} should be a token", def.name);
            assert!(def.fallback.is_none(), "more than one fallback assigned to token {}", def.name);
            def.fallback = Some(to);
        }
    }

    /// A rule with a semantic action, `lhs ::= rhs. [prec] { ... }`, in file order.
    pub fn rule(&mut self, lhs: Symbol, rhs: &[Symbol], prec: Option<Symbol>) {
        self.push_rule(lhs, rhs, prec, true);
    }

    /// A rule without any code, `lhs ::= rhs. [prec]`; lemon numbers these after all the others.
    pub fn rule_without_action(&mut self, lhs: Symbol, rhs: &[Symbol], prec: Option<Symbol>) {
        self.push_rule(lhs, rhs, prec, false);
    }

    fn push_rule(&mut self, lhs: Symbol, rhs: &[Symbol], prec: Option<Symbol>, has_action: bool) {
        assert!(!self.symbols[lhs as usize].terminal, "the left side of a rule must be a nonterminal");
        if let Some(p) = prec {
            assert!(self.symbols[p as usize].terminal, "a precedence mark must be a terminal");
        }
        self.rules.push(RuleDef { lhs, rhs: rhs.to_vec(), prec, has_action });
    }

    /// `%start_symbol`; by default the left side of the first rule.
    pub fn start_symbol(&mut self, symbol: Symbol) {
        self.start = Some(symbol);
    }

    /// `%stack_size`; `0` makes the stack grow without bound, as lemon's `YYSTACKDEPTH<=0`.
    pub fn stack_size(&mut self, depth: usize) {
        self.stack_size = depth;
    }

    pub fn n_terminals(&self) -> usize {
        self.n_terminals
    }

    pub fn n_symbols(&self) -> usize {
        self.symbols.len()
    }

    pub fn symbol_name(&self, symbol: Symbol) -> &str {
        &self.symbols[symbol as usize].name
    }

    pub fn symbol(&self, name: &str) -> Option<Symbol> {
        self.symbols.iter().position(|s| s.name == name).map(|i| i as Symbol)
    }

    /// Lemon's number for each rule, by position in file order: rules with an action first.
    fn lemon_numbers(&self) -> Vec<usize> {
        let mut out = vec![0; self.rules.len()];
        let mut next = 0;
        for pass in [true, false] {
            for (i, r) in self.rules.iter().enumerate() {
                if r.has_action == pass {
                    out[i] = next;
                    next += 1;
                }
            }
        }
        out
    }

    /// Lemon's number for the `index`-th rule in file order.
    pub fn lemon_rule_number(&self, index: usize) -> RuleId {
        self.lemon_numbers()[index] as RuleId
    }

    /// Generates the tables, as lemon does. Problems lemon reports but still generates tables for
    /// (a rule that can never be reduced, the start symbol on a right side, a nonterminal without
    /// rules) are listed in [`Tables::errors`]; conflicts are counted in [`Tables::conflicts`].
    pub fn build(&self) -> Result<Tables, GrammarError> {
        if self.rules.is_empty() {
            return Err(GrammarError("Empty grammar.".into()));
        }
        let start = self.start.unwrap_or(self.rules[0].lhs);
        if self.symbols[start as usize].terminal {
            return Err(GrammarError(format!("the start symbol {} is not a nonterminal", self.symbol_name(start))));
        }
        Ok(Gen::new(self, start).run())
    }
}

/// What the parser does on a lookahead.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Action {
    /// Push the lookahead and go to the state.
    Shift(StateId),
    /// Push the lookahead, then reduce by the rule before looking at the next token (lemon's
    /// SHIFTREDUCE: the target state could only reduce by that rule).
    ShiftReduce(RuleId),
    /// Reduce by the rule; the lookahead stays.
    Reduce(RuleId),
    Accept,
    Error,
}

/// One line of a state in lemon's `parser.out`, including what precedence dropped and what was
/// left in conflict.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EntryKind {
    Shift(StateId),
    ShiftReduce(RuleId),
    Reduce(RuleId),
    Accept,
    /// `%nonassoc` turned the shift into a syntax error.
    Error,
    /// A shift left in an unresolved shift/shift conflict (lemon keeps the first).
    ShiftConflict(StateId),
    /// A reduce left in an unresolved shift/reduce or reduce/reduce conflict (it loses).
    ReduceConflict(RuleId),
    /// A shift dropped by precedence.
    ShiftDropped(StateId),
    /// A reduce dropped by precedence.
    ReduceDropped(RuleId),
}

/// A state's action on one symbol, with the symbol lemon substituted when it bypassed a unit
/// rule without code (`/* because X==Y */` in `parser.out`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Entry {
    pub symbol: Symbol,
    pub kind: EntryKind,
    pub because: Option<Symbol>,
}

/// One state of the final automaton.
#[derive(Clone, Debug)]
pub struct StateTable {
    /// Every action in lemon's order (by symbol), the default excluded.
    pub entries: Vec<Entry>,
    /// The default reduce, taken for every terminal without an explicit action.
    pub default: Option<RuleId>,
    /// The effective action per symbol (`None`: not explicit, use the default).
    lookup: Vec<Option<Action>>,
}

/// A rule of the generated parser, indexed by its lemon number.
#[derive(Clone, Debug)]
pub struct RuleInfo {
    pub lhs: Symbol,
    pub rhs: Vec<Symbol>,
    /// The precedence symbol: the `[X]` mark, else the first right-side terminal with one.
    pub prec: Option<Symbol>,
    pub has_action: bool,
    /// Position in the grammar file.
    pub index: usize,
}

/// The generated parser tables.
#[derive(Clone, Debug)]
pub struct Tables {
    names: Vec<String>,
    precs: Vec<Option<i32>>,
    n_terminals: usize,
    rules: Vec<RuleInfo>,
    states: Vec<StateTable>,
    fallback: Vec<Symbol>,
    stack_size: usize,
    conflicts: usize,
    resolved: usize,
    n_states_total: usize,
    errors: Vec<String>,
}

impl Tables {
    pub fn n_terminals(&self) -> usize {
        self.n_terminals
    }

    pub fn n_symbols(&self) -> usize {
        self.names.len()
    }

    pub fn symbol_name(&self, symbol: Symbol) -> &str {
        &self.names[symbol as usize]
    }

    pub fn symbol(&self, name: &str) -> Option<Symbol> {
        self.names.iter().position(|n| n == name).map(|i| i as Symbol)
    }

    /// The rules, indexed by lemon number.
    pub fn rules(&self) -> &[RuleInfo] {
        &self.rules
    }

    /// The states lemon emits (`YYNSTATE`); state 0 is the start state.
    pub fn states(&self) -> &[StateTable] {
        &self.states
    }

    /// Every LR(0) state, including the auto-reduce states lemon drops from the tables.
    pub fn n_states_total(&self) -> usize {
        self.n_states_total
    }

    /// Unresolved conflicts: lemon's "N parsing conflicts".
    pub fn conflicts(&self) -> usize {
        self.conflicts
    }

    /// Conflicts precedence resolved: a dropped shift or reduce, or a `%nonassoc` error.
    pub fn resolved_conflicts(&self) -> usize {
        self.resolved
    }

    /// Non-fatal errors lemon reports (it still writes the tables but fails the build).
    pub fn errors(&self) -> &[String] {
        &self.errors
    }

    /// `%stack_size` (0: unbounded).
    pub fn stack_size(&self) -> usize {
        self.stack_size
    }

    /// The `%fallback` token of a terminal.
    pub fn fallback(&self, token: Symbol) -> Option<Symbol> {
        self.fallback.get(token as usize).copied().filter(|&f| f != 0)
    }

    /// The explicit action of a state on a symbol (`yy_action`), without fallback or default.
    pub fn action(&self, state: StateId, symbol: Symbol) -> Option<Action> {
        self.states[state as usize].lookup[symbol as usize]
    }

    /// `yy_find_shift_action`: the explicit action, else the fallback token's, else the default.
    pub fn find_shift_action(&self, state: StateId, token: Symbol) -> Action {
        let st = &self.states[state as usize];
        let mut la = token;
        for _ in 0..=self.n_terminals {
            if let Some(a) = st.lookup[la as usize] {
                return a;
            }
            match self.fallback(la) {
                Some(f) => la = f,
                None => break,
            }
        }
        st.default.map_or(Action::Error, Action::Reduce)
    }

    /// `yy_find_reduce_action`: the goto after reducing to `nonterminal`. A SHIFTREDUCE on a
    /// nonterminal is a plain reduce (lemon's `compute_action`).
    pub fn find_reduce_action(&self, state: StateId, nonterminal: Symbol) -> Action {
        let st = &self.states[state as usize];
        match st.lookup[nonterminal as usize] {
            Some(Action::ShiftReduce(r)) => Action::Reduce(r),
            Some(a) => a,
            None => st.default.map_or(Action::Error, Action::Reduce),
        }
    }

    /// A compact rendering of every state, one line each: `N:` then the entries as
    /// `<symbol><code><arg>`, codes `s` shift, `t` shift-reduce, `r` reduce, `a` accept, `e`
    /// error, `S`/`R` shift/reduce left in a conflict, `x`/`y` shift/reduce dropped by
    /// precedence, with `^<symbol>` for a bypassed unit rule, and `*r<rule>` for the default.
    pub fn report(&self) -> String {
        let mut out = String::new();
        for (n, st) in self.states.iter().enumerate() {
            out.push_str(&format!("{n}:"));
            let mut sep = "";
            for e in &st.entries {
                let (code, arg) = match e.kind {
                    EntryKind::Shift(s) => ('s', Some(s)),
                    EntryKind::ShiftReduce(r) => ('t', Some(r)),
                    EntryKind::Reduce(r) => ('r', Some(r)),
                    EntryKind::Accept => ('a', None),
                    EntryKind::Error => ('e', None),
                    EntryKind::ShiftConflict(s) => ('S', Some(s)),
                    EntryKind::ReduceConflict(r) => ('R', Some(r)),
                    EntryKind::ShiftDropped(s) => ('x', Some(s)),
                    EntryKind::ReduceDropped(r) => ('y', Some(r)),
                };
                out.push_str(&format!("{sep}{}{code}", e.symbol));
                if let Some(a) = arg {
                    out.push_str(&a.to_string());
                }
                if let Some(b) = e.because {
                    out.push_str(&format!("^{b}"));
                }
                sep = " ";
            }
            if let Some(d) = st.default {
                out.push_str(&format!("{sep}*r{d}"));
            }
            out.push('\n');
        }
        out
    }

    /// The rules as lemon lists them at the end of `parser.out`.
    pub fn rules_report(&self) -> String {
        let mut out = String::new();
        for (n, r) in self.rules.iter().enumerate() {
            out.push_str(&format!("{n:4}: {} ::=", self.symbol_name(r.lhs)));
            for &s in &r.rhs {
                out.push(' ');
                out.push_str(self.symbol_name(s));
            }
            out.push('.');
            if let Some(p) = r.prec {
                out.push_str(&format!(" [{} precedence={}]", self.symbol_name(p), self.precs[p as usize].unwrap_or(-1)));
            }
            out.push('\n');
        }
        out
    }
}

// ---------------------------------------------------------------------------------------------
// The generator.

/// A set of terminals (lemon's `char *` sets).
#[derive(Clone, Debug, PartialEq, Eq)]
struct Bits(Vec<u64>);

impl Bits {
    fn new(n: usize) -> Self {
        Bits(vec![0; n.div_ceil(64).max(1)])
    }

    fn add(&mut self, i: usize) -> bool {
        let (w, b) = (i / 64, 1u64 << (i % 64));
        let had = self.0[w] & b != 0;
        self.0[w] |= b;
        !had
    }

    fn has(&self, i: usize) -> bool {
        self.0[i / 64] & (1u64 << (i % 64)) != 0
    }

    fn union(&mut self, other: &Bits) -> bool {
        let mut changed = false;
        for (a, &b) in self.0.iter_mut().zip(&other.0) {
            let n = *a | b;
            changed |= n != *a;
            *a = n;
        }
        changed
    }
}

/// `enum e_action`, in lemon's order (the sort key).
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum Kind {
    Shift,
    Accept,
    Reduce,
    Error,
    SsConflict,
    SrConflict,
    RrConflict,
    ShResolved,
    RdResolved,
    NotUsed,
    ShiftReduce,
}

/// `struct action`: `x` is a state (shift kinds) or a rule in file order (reduce kinds).
#[derive(Clone, Copy, Debug)]
struct Act {
    sym: usize,
    kind: Kind,
    x: usize,
    sp_opt: Option<usize>,
    /// Allocation order: lemon's last tie-break compares the action addresses.
    seq: usize,
}

/// `struct config`: a rule with a dot, its follow set and propagation links.
#[derive(Clone, Debug)]
struct Config {
    rule: usize,
    dot: usize,
    fws: Bits,
    fwd: Vec<usize>,
    bwd: Vec<usize>,
}

#[derive(Clone, Debug)]
struct LState {
    basis: Vec<usize>,
    configs: Vec<usize>,
    actions: Vec<Act>,
    auto_reduce: bool,
    dflt: Option<usize>,
}

struct Gen<'g> {
    g: &'g Grammar,
    start: usize,
    nterm: usize,
    nsym: usize,
    /// `sp->rule`: rules of each nonterminal (lemon prepends, so in reverse file order).
    rules_of: Vec<Vec<usize>>,
    first: Vec<Bits>,
    lambda: Vec<bool>,
    precsym: Vec<Option<usize>>,
    lhs_start: Vec<bool>,
    configs: Vec<Config>,
    states: Vec<LState>,
    state_map: HashMap<Vec<(usize, usize)>, usize>,
    seq: usize,
    conflicts: usize,
    resolved: usize,
    errors: Vec<String>,
}

impl<'g> Gen<'g> {
    fn new(g: &'g Grammar, start: Symbol) -> Self {
        let nsym = g.symbols.len();
        let mut rules_of = vec![Vec::new(); nsym];
        for (i, r) in g.rules.iter().enumerate() {
            rules_of[r.lhs as usize].insert(0, i);
        }
        Gen {
            g,
            start: start as usize,
            nterm: g.n_terminals,
            nsym,
            rules_of,
            first: Vec::new(),
            lambda: vec![false; nsym],
            precsym: Vec::new(),
            lhs_start: vec![false; g.rules.len()],
            configs: Vec::new(),
            states: Vec::new(),
            state_map: HashMap::new(),
            seq: 0,
            conflicts: 0,
            resolved: 0,
            errors: Vec::new(),
        }
    }

    fn rhs(&self, rule: usize) -> &[Symbol] {
        &self.g.rules[rule].rhs
    }

    fn is_terminal(&self, s: usize) -> bool {
        s < self.nterm
    }

    fn prec(&self, s: usize) -> Option<(i32, Assoc)> {
        self.g.symbols[s].prec
    }

    fn act(&mut self, sym: usize, kind: Kind, x: usize) -> Act {
        self.seq += 1;
        Act { sym, kind, x, sp_opt: None, seq: self.seq }
    }

    fn run(mut self) -> Tables {
        self.find_rule_precedences();
        self.find_first_sets();
        self.find_states();
        self.find_links();
        self.find_follow_sets();
        self.find_actions();
        self.compress_tables();
        self.finish()
    }

    /// `FindRulePrecedences`: rules without `[X]` take the first right-side symbol with one.
    fn find_rule_precedences(&mut self) {
        self.precsym = self
            .g
            .rules
            .iter()
            .map(|r| r.prec.map(|p| p as usize).or_else(|| r.rhs.iter().map(|&s| s as usize).find(|&s| self.g.symbols[s].prec.is_some())))
            .collect();
    }

    /// `FindFirstSets`.
    fn find_first_sets(&mut self) {
        let order = self.lemon_order();
        self.first = (0..self.nsym).map(|_| Bits::new(self.nterm + 1)).collect();
        loop {
            let mut progress = false;
            for &ri in &order {
                let r = &self.g.rules[ri];
                if self.lambda[r.lhs as usize] {
                    continue;
                }
                if r.rhs.iter().all(|&s| self.lambda[s as usize]) {
                    self.lambda[r.lhs as usize] = true;
                    progress = true;
                }
            }
            if !progress {
                break;
            }
        }
        loop {
            let mut progress = false;
            for &ri in &order {
                let s1 = self.g.rules[ri].lhs as usize;
                for &s2 in &self.g.rules[ri].rhs {
                    let s2 = s2 as usize;
                    if self.is_terminal(s2) {
                        progress |= self.first[s1].add(s2);
                        break;
                    } else if s1 == s2 {
                        if !self.lambda[s1] {
                            break;
                        }
                    } else {
                        let f = self.first[s2].clone();
                        progress |= self.first[s1].union(&f);
                        if !self.lambda[s2] {
                            break;
                        }
                    }
                }
            }
            if !progress {
                break;
            }
        }
    }

    /// The order of lemon's rule list after `Rule_sort` (by lemon number).
    fn lemon_order(&self) -> Vec<usize> {
        let nums = self.g.lemon_numbers();
        let mut order: Vec<usize> = (0..self.g.rules.len()).collect();
        order.sort_by_key(|&i| nums[i]);
        order
    }

    /// `FindStates`.
    fn find_states(&mut self) {
        for r in &self.g.rules {
            if r.rhs.iter().any(|&s| s as usize == self.start) {
                self.errors.push(format!(
                    "The start symbol \"{}\" occurs on the right-hand side of a rule. This will result in a parser which does not work properly.",
                    self.g.symbols[self.start].name
                ));
            }
        }
        let basis: Vec<(usize, usize, Vec<usize>)> = self.rules_of[self.start].clone().into_iter().map(|r| (r, 0, Vec::new())).collect();
        for &r in &self.rules_of[self.start] {
            self.lhs_start[r] = true;
        }
        let s0 = self.get_state(basis);
        for c in self.states[s0].basis.clone() {
            self.configs[c].fws.add(0);
        }
    }

    fn new_config(&mut self, rule: usize, dot: usize) -> usize {
        self.configs.push(Config { rule, dot, fws: Bits::new(self.nterm + 1), fwd: Vec::new(), bwd: Vec::new() });
        self.configs.len() - 1
    }

    /// `getstate`: the state with this basis, built (with its successors) if it is new.
    fn get_state(&mut self, mut basis: Vec<(usize, usize, Vec<usize>)>) -> usize {
        basis.sort_by_key(|b| (b.0, b.1));
        let key: Vec<(usize, usize)> = basis.iter().map(|b| (b.0, b.1)).collect();
        if let Some(&s) = self.state_map.get(&key) {
            for (k, b) in basis.into_iter().enumerate() {
                let c = self.states[s].basis[k];
                self.configs[c].bwd.extend(b.2);
            }
            return s;
        }
        let mut table: HashMap<(usize, usize), usize> = HashMap::new();
        let mut current = Vec::new();
        for (rule, dot, bwd) in basis {
            let c = self.new_config(rule, dot);
            self.configs[c].bwd = bwd;
            table.insert((rule, dot), c);
            current.push(c);
        }
        let basis_ids = current.clone();
        // Configlist_closure
        let mut i = 0;
        while i < current.len() {
            let cfp = current[i];
            i += 1;
            let (rule, dot) = (self.configs[cfp].rule, self.configs[cfp].dot);
            let rhs = self.rhs(rule).to_vec();
            if dot >= rhs.len() {
                continue;
            }
            let sp = rhs[dot] as usize;
            if self.is_terminal(sp) {
                continue;
            }
            if self.rules_of[sp].is_empty() {
                let msg = format!("Nonterminal \"{}\" has no rules.", self.g.symbols[sp].name);
                if !self.errors.contains(&msg) {
                    self.errors.push(msg);
                }
            }
            for newrp in self.rules_of[sp].clone() {
                let newcfp = match table.get(&(newrp, 0)) {
                    Some(&c) => c,
                    None => {
                        let c = self.new_config(newrp, 0);
                        table.insert((newrp, 0), c);
                        current.push(c);
                        c
                    }
                };
                let mut j = dot + 1;
                while j < rhs.len() {
                    let xsp = rhs[j] as usize;
                    if self.is_terminal(xsp) {
                        self.configs[newcfp].fws.add(xsp);
                        break;
                    }
                    let f = self.first[xsp].clone();
                    self.configs[newcfp].fws.union(&f);
                    if !self.lambda[xsp] {
                        break;
                    }
                    j += 1;
                }
                if j == rhs.len() {
                    self.configs[cfp].fwd.push(newcfp);
                }
            }
        }
        current.sort_by_key(|&c| (self.configs[c].rule, self.configs[c].dot));
        let s = self.states.len();
        self.states.push(LState { basis: basis_ids, configs: current, actions: Vec::new(), auto_reduce: false, dflt: None });
        self.state_map.insert(key, s);
        self.build_shifts(s);
        s
    }

    /// `buildshifts`: one successor per symbol after a dot, in configuration order.
    fn build_shifts(&mut self, s: usize) {
        let cfgs = self.states[s].configs.clone();
        let mut done = vec![false; cfgs.len()];
        for i in 0..cfgs.len() {
            if done[i] {
                continue;
            }
            let c = &self.configs[cfgs[i]];
            let rhs = self.rhs(c.rule);
            if c.dot >= rhs.len() {
                continue;
            }
            let sp = rhs[c.dot];
            let mut basis = Vec::new();
            for j in i..cfgs.len() {
                if done[j] {
                    continue;
                }
                let b = &self.configs[cfgs[j]];
                let brhs = self.rhs(b.rule);
                if b.dot >= brhs.len() || brhs[b.dot] != sp {
                    continue;
                }
                done[j] = true;
                basis.push((b.rule, b.dot + 1, vec![cfgs[j]]));
            }
            let ns = self.get_state(basis);
            let a = self.act(sp as usize, Kind::Shift, ns);
            self.states[s].actions.push(a);
        }
    }

    /// `FindLinks`: back links become forward links.
    fn find_links(&mut self) {
        for c in 0..self.configs.len() {
            for b in self.configs[c].bwd.clone() {
                self.configs[b].fwd.push(c);
            }
        }
    }

    /// `FindFollowSets`.
    fn find_follow_sets(&mut self) {
        let mut complete = vec![false; self.configs.len()];
        loop {
            let mut progress = false;
            for s in 0..self.states.len() {
                for &c in &self.states[s].configs {
                    if complete[c] {
                        continue;
                    }
                    let fws = self.configs[c].fws.clone();
                    for k in 0..self.configs[c].fwd.len() {
                        let t = self.configs[c].fwd[k];
                        if self.configs[t].fws.union(&fws) {
                            complete[t] = false;
                            progress = true;
                        }
                    }
                    complete[c] = true;
                }
            }
            if !progress {
                break;
            }
        }
    }

    fn sort_actions(&self, acts: &mut [Act]) {
        acts.sort_by(|a, b| {
            a.sym.cmp(&b.sym).then(a.kind.cmp(&b.kind)).then_with(|| {
                if matches!(a.kind, Kind::Reduce | Kind::ShiftReduce) { a.x.cmp(&b.x) } else { std::cmp::Ordering::Equal }
            })
            // `(int)(ap2 - ap1)`: the later allocation first.
            .then(b.seq.cmp(&a.seq))
        });
    }

    /// `FindActions`.
    fn find_actions(&mut self) {
        for s in 0..self.states.len() {
            for ci in 0..self.states[s].configs.len() {
                let c = self.states[s].configs[ci];
                let (rule, dot) = (self.configs[c].rule, self.configs[c].dot);
                if dot != self.rhs(rule).len() {
                    continue;
                }
                for j in 0..self.nterm {
                    if self.configs[c].fws.has(j) {
                        let a = self.act(j, Kind::Reduce, rule);
                        self.states[s].actions.push(a);
                    }
                }
            }
        }
        let a = self.act(self.start, Kind::Accept, 0);
        self.states[0].actions.push(a);
        for s in 0..self.states.len() {
            let mut acts = std::mem::take(&mut self.states[s].actions);
            self.sort_actions(&mut acts);
            for i in 0..acts.len() {
                let mut j = i + 1;
                while j < acts.len() && acts[j].sym == acts[i].sym {
                    let (x, y) = (acts[i], acts[j]);
                    let (nx, ny, errs) = self.resolve_conflict(x, y);
                    if errs == 0 && (nx, ny) != (x.kind, y.kind) {
                        self.resolved += 1;
                    }
                    acts[i].kind = nx;
                    acts[j].kind = ny;
                    self.conflicts += errs;
                    j += 1;
                }
            }
            self.states[s].actions = acts;
        }
        let mut can_reduce = vec![false; self.g.rules.len()];
        for st in &self.states {
            for a in &st.actions {
                if a.kind == Kind::Reduce {
                    can_reduce[a.x] = true;
                }
            }
        }
        for (i, ok) in can_reduce.into_iter().enumerate() {
            if !ok {
                self.errors.push(format!("Rule {} can not be reduced.", i));
            }
        }
    }

    /// `resolve_conflict`: the new kinds of the two actions and whether a conflict remains.
    fn resolve_conflict(&self, apx: Act, apy: Act) -> (Kind, Kind, usize) {
        let (mut kx, mut ky, mut errs) = (apx.kind, apy.kind, 0);
        if kx == Kind::Shift && ky == Kind::Shift {
            ky = Kind::SsConflict;
            errs += 1;
        }
        if kx == Kind::Shift && ky == Kind::Reduce {
            let spx = self.prec(apx.sym);
            let spy = self.precsym[apy.x].and_then(|p| self.prec(p));
            match (spx, spy) {
                (Some((px, ax)), Some((py, _))) => {
                    if px > py {
                        ky = Kind::RdResolved;
                    } else if px < py {
                        kx = Kind::ShResolved;
                    } else {
                        match ax {
                            Assoc::Right => ky = Kind::RdResolved,
                            Assoc::Left => kx = Kind::ShResolved,
                            Assoc::Nonassoc => kx = Kind::Error,
                        }
                    }
                }
                _ => {
                    ky = Kind::SrConflict;
                    errs += 1;
                }
            }
        } else if kx == Kind::Reduce && ky == Kind::Reduce {
            let spx = self.precsym[apx.x].and_then(|p| self.prec(p));
            let spy = self.precsym[apy.x].and_then(|p| self.prec(p));
            match (spx, spy) {
                (Some((px, _)), Some((py, _))) if px != py => {
                    if px > py {
                        ky = Kind::RdResolved;
                    } else {
                        kx = Kind::RdResolved;
                    }
                }
                _ => {
                    ky = Kind::RrConflict;
                    errs += 1;
                }
            }
        }
        (kx, ky, errs)
    }

    /// `CompressTables`.
    fn compress_tables(&mut self) {
        let default_sym = self.nsym;
        for s in 0..self.states.len() {
            let mut acts = std::mem::take(&mut self.states[s].actions);
            let mut nbest = 0;
            let mut rbest: Option<usize> = None;
            for i in 0..acts.len() {
                if acts[i].kind != Kind::Reduce {
                    continue;
                }
                let rp = acts[i].x;
                if self.lhs_start[rp] || Some(rp) == rbest {
                    continue;
                }
                let mut n = 1;
                for a2 in &acts[i + 1..] {
                    if a2.kind != Kind::Reduce || Some(a2.x) == rbest {
                        continue;
                    }
                    if a2.x == rp {
                        n += 1;
                    }
                }
                if n > nbest {
                    nbest = n;
                    rbest = Some(rp);
                }
            }
            if let Some(rb) = rbest.filter(|_| nbest >= 1) {
                let first = acts.iter().position(|a| a.kind == Kind::Reduce && a.x == rb).expect("best reduce");
                acts[first].sym = default_sym;
                for a in &mut acts[first + 1..] {
                    if a.kind == Kind::Reduce && a.x == rb {
                        a.kind = Kind::NotUsed;
                    }
                }
                self.sort_actions(&mut acts);
                let blocked = acts.iter().any(|a| a.kind == Kind::Shift || (a.kind == Kind::Reduce && a.x != rb));
                if !blocked {
                    self.states[s].auto_reduce = true;
                    self.states[s].dflt = Some(rb);
                }
            }
            self.states[s].actions = acts;
        }
        // Shifts into a state that can only reduce become SHIFTREDUCE.
        for s in 0..self.states.len() {
            for i in 0..self.states[s].actions.len() {
                let a = self.states[s].actions[i];
                if a.kind != Kind::Shift {
                    continue;
                }
                let next = &self.states[a.x];
                if let Some(r) = next.dflt.filter(|_| next.auto_reduce) {
                    let a = &mut self.states[s].actions[i];
                    a.kind = Kind::ShiftReduce;
                    a.x = r;
                }
            }
        }
        // A SHIFTREDUCE on a nonterminal by a code-less unit rule takes the action of the rule's
        // left side instead.
        for s in 0..self.states.len() {
            let acts = &mut self.states[s].actions;
            let mut i = 0;
            let mut guard = 0;
            while i < acts.len() {
                let ap = acts[i];
                let bypass = ap.kind == Kind::ShiftReduce && {
                    let r = &self.g.rules[ap.x];
                    !r.has_action && r.rhs.len() == 1 && ap.sym >= self.nterm
                };
                // `guard` stops a cycle of unit rules, where lemon would loop forever.
                if !bypass || guard > acts.len() {
                    i += 1;
                    guard = 0;
                    continue;
                }
                let r = &self.g.rules[ap.x];
                let lhs = r.lhs as usize;
                let j = (0..acts.len()).find(|&j| j != i && acts[j].sym == lhs).expect("action on the rule's left side");
                let ap2 = acts[j];
                acts[i].sp_opt = Some(ap2.sym);
                acts[i].kind = ap2.kind;
                acts[i].x = ap2.x;
                guard += 1;
            }
        }
    }

    /// `ResortStates` and the public tables.
    fn finish(self) -> Tables {
        let n = self.states.len();
        let nums = self.g.lemon_numbers();
        let effective = |k: Kind| matches!(k, Kind::Shift | Kind::ShiftReduce | Kind::Reduce | Kind::Error | Kind::Accept);
        let mut ntkn = vec![0usize; n];
        let mut nnt = vec![0usize; n];
        for (s, st) in self.states.iter().enumerate() {
            for a in &st.actions {
                if !effective(a.kind) {
                    continue;
                }
                if a.sym < self.nterm {
                    ntkn[s] += 1;
                } else if a.sym < self.nsym {
                    nnt[s] += 1;
                }
            }
        }
        let mut order: Vec<usize> = (1..n).collect();
        order.sort_by(|&a, &b| nnt[b].cmp(&nnt[a]).then(ntkn[b].cmp(&ntkn[a])).then(b.cmp(&a)));
        order.insert(0, 0);
        let mut number = vec![0usize; n];
        for (i, &s) in order.iter().enumerate() {
            number[s] = i;
        }
        let mut nx = n;
        while nx > 1 && self.states[order[nx - 1]].auto_reduce {
            nx -= 1;
        }
        let st_id = |s: usize| number[s] as StateId;
        let rule_id = |r: usize| nums[r] as RuleId;
        let mut states = Vec::with_capacity(nx);
        for &s in &order[..nx] {
            let st = &self.states[s];
            let mut entries = Vec::new();
            let mut default = None;
            let mut lookup = vec![None; self.nsym];
            for a in &st.actions {
                if a.sym == self.nsym {
                    default = Some(rule_id(a.x));
                    continue;
                }
                let kind = match a.kind {
                    Kind::Shift => EntryKind::Shift(st_id(a.x)),
                    Kind::ShiftReduce => EntryKind::ShiftReduce(rule_id(a.x)),
                    Kind::Reduce => EntryKind::Reduce(rule_id(a.x)),
                    Kind::Accept => EntryKind::Accept,
                    Kind::Error => EntryKind::Error,
                    Kind::SsConflict => EntryKind::ShiftConflict(st_id(a.x)),
                    Kind::SrConflict | Kind::RrConflict => EntryKind::ReduceConflict(rule_id(a.x)),
                    Kind::ShResolved => EntryKind::ShiftDropped(st_id(a.x)),
                    Kind::RdResolved => EntryKind::ReduceDropped(rule_id(a.x)),
                    Kind::NotUsed => continue,
                };
                let action = match kind {
                    EntryKind::Shift(t) => Some(Action::Shift(t)),
                    EntryKind::ShiftReduce(r) => Some(Action::ShiftReduce(r)),
                    EntryKind::Reduce(r) => Some(Action::Reduce(r)),
                    EntryKind::Accept => Some(Action::Accept),
                    EntryKind::Error => Some(Action::Error),
                    _ => None,
                };
                // Two explicit actions on one symbol (a %nonassoc error next to its reduce): the
                // later one overwrites the earlier in lemon's yy_action[].
                if action.is_some() {
                    lookup[a.sym] = action;
                }
                entries.push(Entry { symbol: a.sym as Symbol, kind, because: a.sp_opt.map(|b| b as Symbol) });
            }
            states.push(StateTable { entries, default, lookup });
        }
        let mut rules: Vec<RuleInfo> = self
            .g
            .rules
            .iter()
            .enumerate()
            .map(|(i, r)| RuleInfo { lhs: r.lhs, rhs: r.rhs.clone(), prec: self.precsym[i].map(|p| p as Symbol), has_action: r.has_action, index: i })
            .collect();
        rules.sort_by_key(|r| nums[r.index]);
        Tables {
            names: self.g.symbols.iter().map(|s| s.name.clone()).collect(),
            precs: self.g.symbols.iter().map(|s| s.prec.map(|p| p.0)).collect(),
            n_terminals: self.nterm,
            rules,
            states,
            fallback: self.g.symbols[..self.nterm].iter().map(|s| s.fallback.unwrap_or(0)).collect(),
            stack_size: self.g.stack_size,
            conflicts: self.conflicts,
            resolved: self.resolved,
            n_states_total: n,
            errors: self.errors,
        }
    }
}

// ---------------------------------------------------------------------------------------------
// The driver.

/// The grammar's actions: lemon's reduce code, `%syntax_error`, `%stack_overflow`,
/// `%parse_failure` and `%parse_accept`. Values popped during error handling are dropped (lemon
/// runs their destructors).
pub trait Handler<V> {
    /// Reduces by `rule` (lemon numbering) with the right side's values; returns the left side's.
    fn reduce(&mut self, rule: RuleId, rhs: Vec<V>) -> V;
    /// `%syntax_error`: `token` (as fed, before any fallback) has no action.
    fn syntax_error(&mut self, _token: Symbol, _value: &V) {}
    /// `%stack_overflow`, after the stack has been emptied.
    fn stack_overflow(&mut self) {}
    /// `%parse_failure`: a syntax error at end of input, after the stack has been emptied.
    fn parse_failure(&mut self) {}
    /// `%parse_accept`, with the start symbol's value.
    fn accept(&mut self, _value: V) {}
}

struct StackEntry<V> {
    /// `stateno`: a state, or the reduce a SHIFTREDUCE left pending, or the accept.
    act: Action,
    major: Symbol,
    value: Option<V>,
}

/// `lempar.c`'s parser: feed it tokens one at a time with [`Parser::feed`], end with
/// [`EOF`].
pub struct Parser<'t, V> {
    tables: &'t Tables,
    stack: Vec<StackEntry<V>>,
    /// `yyerrcnt`: syntax errors are reported again only after three shifts.
    errcnt: i32,
    recovery: bool,
}

impl<'t, V> Parser<'t, V> {
    /// A parser with lemon's default error handling (`YYNOERRORRECOVERY` not defined, as in
    /// RediSearch).
    pub fn new(tables: &'t Tables) -> Self {
        Self::with_error_recovery(tables, true)
    }

    /// `recovery == false` is lemon built with `YYNOERRORRECOVERY`: every syntax error is
    /// reported, the token dropped, and nothing else happens (no `%parse_failure`).
    pub fn with_error_recovery(tables: &'t Tables, recovery: bool) -> Self {
        Parser { tables, stack: vec![StackEntry { act: Action::Shift(0), major: 0, value: None }], errcnt: -1, recovery }
    }

    /// Entries above the initial one (lemon's `yytos - yystack`).
    pub fn depth(&self) -> usize {
        self.stack.len() - 1
    }

    /// The symbols on the stack, bottom first (lemon's trace "Stack=[...]").
    pub fn stack_symbols(&self) -> Vec<Symbol> {
        self.stack[1..].iter().map(|e| e.major).collect()
    }

    fn overflows(&self) -> bool {
        let depth = self.tables.stack_size;
        depth > 0 && self.stack.len() >= depth
    }

    /// `yyStackOverflow`.
    fn stack_overflow<H: Handler<V>>(&mut self, h: &mut H) {
        self.stack.truncate(1);
        h.stack_overflow();
    }

    /// `Parse(parser, token, value)`.
    pub fn feed<H: Handler<V>>(&mut self, token: Symbol, value: V, h: &mut H) {
        let end_of_input = token == EOF;
        let mut act = self.stack.last().expect("stack").act;
        loop {
            let a = match act {
                Action::Shift(s) => self.tables.find_shift_action(s, token),
                pending => pending,
            };
            match a {
                Action::Reduce(rule) => {
                    if self.tables.rules[rule as usize].rhs.is_empty() && self.overflows() {
                        self.stack_overflow(h);
                        return;
                    }
                    act = self.reduce(rule, h);
                }
                Action::Shift(_) | Action::ShiftReduce(_) => {
                    if self.overflows() {
                        self.stack_overflow(h);
                    } else {
                        let act = match a {
                            Action::ShiftReduce(r) => Action::Reduce(r),
                            s => s,
                        };
                        self.stack.push(StackEntry { act, major: token, value: Some(value) });
                    }
                    if self.recovery {
                        self.errcnt -= 1;
                    }
                    return;
                }
                Action::Accept => {
                    let top = self.stack.pop().expect("accepted value");
                    if self.recovery {
                        self.errcnt = -1;
                    }
                    h.accept(top.value.expect("start symbol value"));
                    return;
                }
                Action::Error => {
                    if !self.recovery {
                        h.syntax_error(token, &value);
                        return;
                    }
                    if self.errcnt <= 0 {
                        h.syntax_error(token, &value);
                    }
                    self.errcnt = 3;
                    drop(value);
                    if end_of_input {
                        self.stack.truncate(1);
                        h.parse_failure();
                        self.errcnt = -1;
                    }
                    return;
                }
            }
        }
    }

    /// `yy_reduce`: pops the right side, runs the action, pushes the left side with its goto.
    fn reduce<H: Handler<V>>(&mut self, rule: RuleId, h: &mut H) -> Action {
        let info = &self.tables.rules[rule as usize];
        let base = self.stack.len() - info.rhs.len();
        let rhs: Vec<V> = self.stack.drain(base..).map(|e| e.value.expect("shifted value")).collect();
        let below = match self.stack.last().expect("stack").act {
            Action::Shift(s) => s,
            other => unreachable!("reduce below a pending action {other:?}"),
        };
        let goto = self.tables.find_reduce_action(below, info.lhs);
        let lhs = info.lhs;
        let value = h.reduce(rule, rhs);
        self.stack.push(StackEntry { act: goto, major: lhs, value: Some(value) });
        goto
    }
}

#[cfg(test)]
mod tests {
    //! Every expectation here comes from lemon itself: each grammar was also written as a `.y`
    //! file, run through RediSearch's `srcutil/lemon.c` with `-p` (its `parser.out`, converted to
    //! [`Tables::report`]'s form) and compiled with `lempar.c` into a traced parser fed the same
    //! token sequences (token values are 1-based positions; `r<rule>` per reduce, `E<value>` per
    //! reported syntax error, `A` accept, `F` `%parse_failure`, `O` `%stack_overflow`).
    use super::*;

    #[derive(Default)]
    struct Trace(Vec<String>);

    impl Handler<usize> for Trace {
        fn reduce(&mut self, rule: RuleId, _rhs: Vec<usize>) -> usize {
            self.0.push(format!("r{rule}"));
            0
        }
        fn syntax_error(&mut self, _token: Symbol, value: &usize) {
            self.0.push(format!("E{value}"));
        }
        fn stack_overflow(&mut self) {
            self.0.push("O".into());
        }
        fn parse_failure(&mut self) {
            self.0.push("F".into());
        }
        fn accept(&mut self, _value: usize) {
            self.0.push("A".into());
        }
    }

    fn run_with(t: &Tables, tokens: &str, recovery: bool) -> String {
        let mut p = Parser::with_error_recovery(t, recovery);
        let mut h = Trace::default();
        let mut pos = 0;
        for name in tokens.split_whitespace() {
            pos += 1;
            p.feed(t.symbol(name).unwrap_or_else(|| panic!("no token {name}")), pos, &mut h);
        }
        p.feed(EOF, pos + 1, &mut h);
        h.0.join(" ")
    }

    /// Compares the tables with lemon's report (states joined by `|`) and the parses with
    /// lemon's traces.
    fn check(t: &Tables, report: &str, traces: &[(&str, &str)]) {
        assert_eq!(t.report().trim_end().replace('\n', "|"), report);
        for (tokens, want) in traces {
            assert_eq!(run_with(t, tokens, true), *want, "{tokens}");
        }
    }

    fn arith() -> Tables {
        // %left PLUS. %left TIMES. %right POW. %token NUM.
        // s ::= e. e ::= e PLUS e. e ::= e TIMES e. e ::= e POW e. e ::= NUM.
        let mut g = Grammar::new();
        let plus = g.terminal("PLUS");
        let times = g.terminal("TIMES");
        let pow = g.terminal("POW");
        let num = g.terminal("NUM");
        g.left(&[plus]);
        g.left(&[times]);
        g.right(&[pow]);
        let s = g.nonterminal("s");
        let e = g.nonterminal("e");
        g.rule(s, &[e], None);
        g.rule(e, &[e, plus, e], None);
        g.rule(e, &[e, times, e], None);
        g.rule(e, &[e, pow, e], None);
        g.rule(e, &[num], None);
        g.build().unwrap()
    }

    #[test]
    fn precedence_and_associativity() {
        let t = arith();
        assert_eq!((t.conflicts(), t.resolved_conflicts(), t.n_states_total()), (0, 9, 9));
        assert!(t.errors().is_empty());
        check(
            &t,
            "0:4t4 5a 6s4|1:4t4 6s6|2:4t4 6s7|3:4t4 6s5|4:0r0 1s3 2s2 3s1|5:1x3 2s2 2y1 3s1 3y1 *r1|6:1x3 2x2 3s1 3y3 *r3|7:1x3 2x2 3s1 3y2 *r2",
            &[
                ("NUM PLUS NUM TIMES NUM", "r4 r4 r4 r2 r1 r0 A"),
                ("NUM TIMES NUM PLUS NUM", "r4 r4 r2 r4 r1 r0 A"),
                ("NUM PLUS NUM PLUS NUM", "r4 r4 r1 r4 r1 r0 A"),
                ("NUM POW NUM POW NUM", "r4 r4 r4 r3 r3 r0 A"),
            ],
        );
    }

    /// Without `%nonassoc`/`error`, lemon reports an error, drops the token and keeps going;
    /// further errors are reported only after three shifts (`yyerrcnt`), and an error on `$` is
    /// a `%parse_failure`.
    #[test]
    fn error_recovery() {
        let t = arith();
        check(
            &t,
            &t.report().trim_end().replace('\n', "|"),
            &[
                ("NUM NUM NUM PLUS NUM NUM", "r4 E2 r4 r1 r0 A"),
                ("NUM NUM PLUS NUM NUM NUM PLUS NUM PLUS NUM NUM", "r4 E2 r4 r1 r4 r1 r4 r1 E11 r0 A"),
                ("PLUS", "E1 F"),
            ],
        );
        // With YYNOERRORRECOVERY every error is reported, and end of input does not fail.
        assert_eq!(run_with(&t, "NUM NUM NUM PLUS NUM NUM", false), "r4 E2 E3 r4 r1 E6 r0 A");
        assert_eq!(run_with(&t, "PLUS", false), "E1 E2");
    }

    fn dangling(prec: &[&str]) -> Tables {
        // [%token IF.] [%left ...] %token IF ELSE X.
        // top ::= s. s ::= IF s. s ::= IF s ELSE s. s ::= X.
        let mut g = Grammar::new();
        let if_ = g.terminal("IF");
        let else_ = g.terminal("ELSE");
        let x = g.terminal("X");
        for p in prec {
            g.left(&[g.symbol(p).unwrap()]);
        }
        let top = g.nonterminal("top");
        let s = g.nonterminal("s");
        g.rule(top, &[s], None);
        g.rule(s, &[if_, s], None);
        g.rule(s, &[if_, s, else_, s], None);
        g.rule(s, &[x], None);
        g.build().unwrap()
    }

    /// The dangling else: an unresolved shift/reduce conflict shifts (and counts), precedence
    /// can resolve it either way.
    #[test]
    fn dangling_else() {
        let t = dangling(&[]);
        assert_eq!((t.conflicts(), t.resolved_conflicts()), (1, 0));
        check(
            &t,
            "0:1s2 3t3 4a 5s4|1:1s2 3t3 5t2|2:1s2 3t3 5s3|3:2s1 2R1 *r1|4:0r0",
            &[("IF IF X ELSE X", "r3 r3 r2 r1 r0 A"), ("IF X ELSE X ELSE X", "r3 r3 r2 E5 r0 A"), ("IF X", "r3 r1 r0 A")],
        );
        let t = dangling(&["IF", "ELSE"]);
        assert_eq!((t.conflicts(), t.resolved_conflicts()), (0, 1));
        check(
            &t,
            "0:1s2 3t3 4a 5s4|1:1s2 3t3 5t2|2:1s2 3t3 5s3|3:2s1 2y1 *r1|4:0r0",
            &[("IF IF X ELSE X", "r3 r3 r2 r1 r0 A"), ("IF X ELSE X ELSE X", "r3 r3 r2 E5 r0 A"), ("IF X", "r3 r1 r0 A")],
        );
        // ELSE below IF: the reduce wins; the state after `IF s` only reduces and disappears.
        let t = dangling(&["ELSE", "IF"]);
        assert_eq!((t.conflicts(), t.resolved_conflicts(), t.states().len()), (0, 1, 4));
        check(
            &t,
            "0:1s2 3t3 4a 5s3|1:1s2 3t3 5t2|2:1s2 3t3 5t1|3:0r0",
            &[("IF IF X ELSE X", "r3 r1 r1 E4 r0 A"), ("IF X ELSE X ELSE X", "r3 r1 E3 r0 A"), ("IF X", "r3 r1 r0 A")],
        );
    }

    /// Reduce/reduce goes to the rule earlier in the file (not the lower lemon number), and the
    /// loser is reported as never reduced.
    #[test]
    fn reduce_reduce_by_rule_order() {
        // %token X. s ::= a. s ::= b. b ::= X. a ::= X.
        let mut g = Grammar::new();
        let x = g.terminal("X");
        let s = g.nonterminal("s");
        let a = g.nonterminal("a");
        let b = g.nonterminal("b");
        g.rule(s, &[a], None);
        g.rule(s, &[b], None);
        g.rule(b, &[x], None);
        g.rule(a, &[x], None);
        let t = g.build().unwrap();
        assert_eq!(t.conflicts(), 1);
        assert_eq!(t.errors(), ["Rule 3 can not be reduced."]);
        check(&t, "0:1t2 2a 3s2 4s1|1:0r1|2:0r0", &[("X", "r2 r1 A"), ("X X", "r2 E2 r1 A"), ("", "E1 F")]);
    }

    /// `%nonassoc` makes the shift a syntax error, but lemon keeps the reduce: when the state can
    /// then only reduce, shifts into it become SHIFTREDUCE and the error is never seen.
    #[test]
    fn nonassoc() {
        // %token EQ ID. %nonassoc EQ. s ::= e. e ::= e EQ e. e ::= ID.
        let mut g = Grammar::new();
        let eq = g.terminal("EQ");
        let id = g.terminal("ID");
        g.nonassoc(&[eq]);
        let s = g.nonterminal("s");
        let e = g.nonterminal("e");
        g.rule(s, &[e], None);
        g.rule(e, &[e, eq, e], None);
        g.rule(e, &[id], None);
        let t = g.build().unwrap();
        assert_eq!((t.conflicts(), t.resolved_conflicts(), t.n_states_total()), (0, 1, 5));
        check(
            &t,
            "0:2t2 3a 4s2|1:2t2 4t1|2:0r0 1s1",
            &[("ID EQ ID", "r2 r2 r1 r0 A"), ("ID EQ ID EQ ID", "r2 r2 r1 r2 r1 r0 A"), ("ID", "r2 r0 A")],
        );
        // %token EQ PLUS ID. %nonassoc EQ. %left PLUS. ... e ::= e PLUS e. — now the state
        // after `e EQ e` also shifts PLUS, so EQ there is an error.
        let mut g = Grammar::new();
        let eq = g.terminal("EQ");
        let plus = g.terminal("PLUS");
        let id = g.terminal("ID");
        g.nonassoc(&[eq]);
        g.left(&[plus]);
        let s = g.nonterminal("s");
        let e = g.nonterminal("e");
        g.rule(s, &[e], None);
        g.rule(e, &[e, eq, e], None);
        g.rule(e, &[e, plus, e], None);
        g.rule(e, &[id], None);
        let t = g.build().unwrap();
        assert_eq!((t.conflicts(), t.resolved_conflicts(), t.n_states_total()), (0, 4, 7));
        check(
            &t,
            "0:3t3 4a 5s3|1:3t3 5t2|2:3t3 5s4|3:0r0 1s2 2s1|4:1e 2s1 2y1 *r1",
            &[
                ("ID EQ ID", "r3 r3 r1 r0 A"),
                ("ID EQ ID EQ ID", "r3 r3 E4 r1 r0 A"),
                ("ID EQ ID PLUS ID", "r3 r3 r3 r2 r1 r0 A"),
                ("ID PLUS ID EQ ID PLUS ID", "r3 r3 r2 r3 r3 r2 r1 r0 A"),
            ],
        );
        assert_eq!(t.find_shift_action(4, eq), Action::Error);
    }

    /// `%fallback ID KW`: a token with no explicit action is retried as its fallback; errors
    /// report the token as fed.
    #[test]
    fn fallback() {
        // %token ID KW SEMI. %fallback ID KW.
        // s ::= list. list ::= list item. list ::= item. item ::= KW SEMI. item ::= ID.
        let mut g = Grammar::new();
        let id = g.terminal("ID");
        let kw = g.terminal("KW");
        let semi = g.terminal("SEMI");
        g.fallback(id, &[kw]);
        let s = g.nonterminal("s");
        let list = g.nonterminal("list");
        let item = g.nonterminal("item");
        g.rule(s, &[list], None);
        g.rule(list, &[list, item], None);
        g.rule(list, &[item], None);
        g.rule(item, &[kw, semi], None);
        g.rule(item, &[id], None);
        let t = g.build().unwrap();
        assert_eq!(t.fallback(kw), Some(id));
        assert_eq!(t.fallback(semi), None);
        check(
            &t,
            "0:1t4 2s2 4a 5s1 6t2|1:0r0 1t4 2s2 6t1|2:3t3",
            &[
                ("KW SEMI ID", "r3 r2 r4 r1 r0 A"),
                ("KW KW", "E2 F"),
                ("KW SEMI KW SEMI", "r3 r2 r3 r1 r0 A"),
                ("ID KW", "r4 r2 E3 F"),
                ("KW", "E2 F"),
                ("KW ID SEMI", "E2 r3 r2 r0 A"),
            ],
        );
    }

    /// A shift into a state that can only reduce is a SHIFTREDUCE: the reduce runs when the next
    /// token arrives, before that token is looked at.
    #[test]
    fn shift_reduce_runs_before_the_error() {
        // %token X Y Z W. s ::= a Z. s ::= a W. a ::= X Y.
        let mut g = Grammar::new();
        let x = g.terminal("X");
        let y = g.terminal("Y");
        let z = g.terminal("Z");
        let w = g.terminal("W");
        let s = g.nonterminal("s");
        let a = g.nonterminal("a");
        g.rule(s, &[a, z], None);
        g.rule(s, &[a, w], None);
        g.rule(a, &[x, y], None);
        let t = g.build().unwrap();
        check(
            &t,
            "0:1s2 5a 6s1|1:3s4 4s3|2:2t2|3:0r1|4:0r0",
            &[("X Y Z", "r2 r0 A"), ("X Y X", "r2 E3 F"), ("X Y", "r2 E3 F"), ("X Z", "E2 F"), ("Y", "E1 F")],
        );
    }

    /// Default reductions apply to every lookahead, errors included, so they run before the
    /// error is detected in a later state.
    #[test]
    fn default_reductions_on_error_lookaheads() {
        // %token NUM PLUS BAD. s ::= e. e ::= e PLUS t. e ::= t. t ::= NUM.
        let mut g = Grammar::new();
        let num = g.terminal("NUM");
        let plus = g.terminal("PLUS");
        let _bad = g.terminal("BAD");
        let s = g.nonterminal("s");
        let e = g.nonterminal("e");
        let t_ = g.nonterminal("t");
        g.rule(s, &[e], None);
        g.rule(e, &[e, plus, t_], None);
        g.rule(e, &[t_], None);
        g.rule(t_, &[num], None);
        let t = g.build().unwrap();
        check(
            &t,
            "0:1t3 4a 5s2 6t2|1:1t3 6t1|2:0r0 2s1",
            &[("NUM BAD", "r3 r2 E2 r0 A"), ("NUM PLUS BAD", "r3 r2 E3 F"), ("NUM PLUS NUM", "r3 r2 r3 r1 r0 A"), ("BAD NUM", "E1 r3 r2 r0 A")],
        );
    }

    fn parens(depth: usize) -> Tables {
        // %token LP RP X. %stack_size N. s ::= e. e ::= LP e RP. e ::= X.
        let mut g = Grammar::new();
        let lp = g.terminal("LP");
        let rp = g.terminal("RP");
        let x = g.terminal("X");
        g.stack_size(depth);
        let s = g.nonterminal("s");
        let e = g.nonterminal("e");
        g.rule(s, &[e], None);
        g.rule(e, &[lp, e, rp], None);
        g.rule(e, &[x], None);
        g.build().unwrap()
    }

    /// `%stack_size N` holds N entries including the bottom one; an overflowing shift empties the
    /// stack and drops the token, so parsing restarts from the start state.
    #[test]
    fn stack_overflow() {
        let report = "0:1s1 3t2 4a 5s3|1:1s1 3t2 5s2|2:2t1|3:0r0";
        check(
            &parens(4),
            report,
            &[
                ("LP LP X RP RP", "r2 O E5 F"),
                ("LP LP LP X RP RP RP", "O E5 F"),
                ("LP LP LP LP LP X RP RP RP RP RP", "O r2 r1 E8 r0 A"),
                ("LP X RP", "r2 r1 r0 A"),
            ],
        );
        // %stack_size 0: the stack grows.
        check(
            &parens(0),
            report,
            &[
                ("LP LP X RP RP", "r2 r1 r1 r0 A"),
                ("LP LP LP X RP RP RP", "r2 r1 r1 r1 r0 A"),
                ("LP LP LP LP LP X RP RP RP RP RP", "r2 r1 r1 r1 r1 r1 r0 A"),
            ],
        );
    }

    /// An empty rule needs room for its left side before it reduces.
    #[test]
    fn stack_overflow_on_empty_rule() {
        // %token LP RP. %stack_size 3. s ::= e. e ::= LP e RP. e ::= .
        let mut g = Grammar::new();
        let lp = g.terminal("LP");
        let rp = g.terminal("RP");
        g.stack_size(3);
        let s = g.nonterminal("s");
        let e = g.nonterminal("e");
        g.rule(s, &[e], None);
        g.rule(e, &[lp, e, rp], None);
        g.rule(e, &[], None);
        check(
            &g.build().unwrap(),
            "0:1s1 3a 4s3 *r2|1:1s1 4s2 *r2|2:2t1|3:0r0",
            &[("LP RP", "r2 O r2 r0 A"), ("LP LP RP RP", "O r2 E4 r0 A"), ("", "r2 r0 A"), ("RP", "r2 E1 r0 A")],
        );
    }

    /// Rules of the start symbol are never default reductions; accept needs `$`.
    #[test]
    fn accept() {
        // %token X. s ::= X. s ::= .
        let mut g = Grammar::new();
        let x = g.terminal("X");
        let s = g.nonterminal("s");
        g.rule(s, &[x], None);
        g.rule(s, &[], None);
        check(&g.build().unwrap(), "0:0r1 1s1 2a|1:0r0", &[("", "r1 A"), ("X", "r0 A"), ("X X", "E2 r0 A"), ("X X X X X", "E2 r0 A")]);
    }

    /// A SHIFTREDUCE on a nonterminal by a unit rule without code takes the action of the rule's
    /// left side instead: `x ::= y.` is never reduced.
    #[test]
    fn unit_rule_without_code_is_bypassed() {
        // %token A B. s ::= x B. x ::= y [code or not]. y ::= A.
        let build = |code: bool| {
            let mut g = Grammar::new();
            let a = g.terminal("A");
            let b = g.terminal("B");
            let s = g.nonterminal("s");
            let x = g.nonterminal("x");
            let y = g.nonterminal("y");
            g.rule(s, &[x, b], None);
            if code {
                g.rule(x, &[y], None);
            } else {
                g.rule_without_action(x, &[y], None);
            }
            g.rule(y, &[a], None);
            g.build().unwrap()
        };
        let t = build(false);
        check(&t, "0:1t1 3a 4s2 5s2^4|1:0r0|2:2s1", &[("A B", "r1 r0 A"), ("A A", "r1 E2 F"), ("B", "E1 F")]);
        assert_eq!(t.rules_report(), "   0: s ::= x B.\n   1: y ::= A.\n   2: x ::= y.\n");
        let t = build(true);
        check(&t, "0:1t2 3a 4s2 5t1|1:0r0|2:2s1", &[("A B", "r2 r1 r0 A"), ("A A", "r2 r1 E2 F"), ("B", "E1 F")]);
    }

    /// Lemon numbers rules with code first, then the others, each group in file order.
    #[test]
    fn lemon_rule_numbering() {
        // %token A. s ::= t. t ::= A. [no code] t ::= t A.
        let mut g = Grammar::new();
        let a = g.terminal("A");
        let s = g.nonterminal("s");
        let t_ = g.nonterminal("t");
        g.rule(s, &[t_], None);
        g.rule_without_action(t_, &[a], None);
        g.rule(t_, &[t_, a], None);
        assert_eq!((0..3).map(|i| g.lemon_rule_number(i)).collect::<Vec<_>>(), [0, 2, 1]);
        let t = g.build().unwrap();
        assert_eq!(t.rules_report(), "   0: s ::= t.\n   1: t ::= t A.\n   2: t ::= A.\n");
        check(&t, "0:1t2 2a 3s1|1:0r0 1t1", &[("A A A", "r2 r1 r1 r0 A")]);
    }

    #[test]
    fn grammar_errors() {
        assert_eq!(Grammar::new().build().unwrap_err(), GrammarError("Empty grammar.".into()));
        let mut g = Grammar::new();
        let a = g.terminal("A");
        let s = g.nonterminal("s");
        let u = g.nonterminal("u");
        g.rule(s, &[a, u], None);
        g.rule(s, &[s, a], None);
        let t = g.build().unwrap();
        assert!(t.errors().iter().any(|e| e.contains("\"s\" occurs on the right-hand side")));
        assert!(t.errors().iter().any(|e| e == "Nonterminal \"u\" has no rules."));
    }
}
